/* Real WordNet data; deterministic overlap scores, with explicit abstention. */
'use strict';
const STOP=new Set('a an the and or of to in on for with by from is are was were be been this that it its as at our their we they has have had will can into during after before more he she his her i you my me them then than also very not no'.split(' '));
const tokenize=text=>new Set((text.toLowerCase().replaceAll('_',' ').match(/[a-z]+/g)||[]).filter(w=>w.length>1&&!STOP.has(w)));
function signature(sense,mode){const weights=Object.create(null);const add=(text,weight)=>{for(const w of tokenize(text))weights[w]=Math.max(weights[w]||0,weight);};add(sense.definition,mode==='classic'?1:3);if(mode==='extended'){add(sense.lemmas.join(' '),3);add(sense.examples.join(' '),2);for(const r of [...sense.hypernyms,...sense.hyponyms])add(r.definition+' '+r.lemmas.join(' '),1);}return weights;}
function analyze(sentence,word,inventory,mode='extended'){
 if(typeof sentence!=='string'||typeof word!=='string')throw Error('Enter a sentence and a target word.');word=word.trim().toLowerCase();if(!['classic','extended'].includes(mode))throw Error('Unknown algorithm.');if(!Object.hasOwn(inventory,word))throw Error('Choose a word in the supported inventory.');if(!sentence.trim()||sentence.length>2000)throw Error('Enter a sentence of 1 to 2000 characters.');if(!(sentence.toLowerCase().match(/[a-z]+/g)||[]).includes(word))throw Error('The exact target word must appear in the sentence.');
 const context=tokenize(sentence);context.delete(word);const ranked=inventory[word].map(s=>{const sig=signature(s,mode);const matches=[...context].filter(t=>Object.hasOwn(sig,t)).sort();return{id:s.id,score:matches.reduce((n,t)=>n+sig[t],0),matches};}).sort((a,b)=>b.score-a.score);
 const best=ranked[0].score,tied=ranked.filter(r=>r.score===best).length,status=best===0?'no_evidence':tied>1?'tied':'resolved';return{word,sentence,mode,status,selected:status==='resolved'?ranked[0].id:null,score:best,margin:best-(ranked[1]?.score||0),context:[...context].sort(),ranked};
}
// Export the pure algorithm for independent cross-language verification.
if(typeof module!=='undefined')module.exports={analyze,tokenize,signature};
if(typeof document!=='undefined'){
 const $=id=>document.getElementById(id),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 let DATA,result,currentView='workspace';
 const senseById=id=>Object.values(DATA.inventory).flat().find(s=>s.id===id);
 function showView(view){if(!['workspace','explorer','evaluation','methodology'].includes(view))view='workspace';currentView=view;for(const el of document.querySelectorAll('.view'))el.hidden=el.id!==view;for(const btn of document.querySelectorAll('.nav')){btn.classList.toggle('active',btn.dataset.view===view);if(btn.dataset.view===view)btn.setAttribute('aria-current','page');else btn.removeAttribute('aria-current');} $('breadcrumb-title').textContent={workspace:'Disambiguation',explorer:'Sense explorer',evaluation:'Evaluation',methodology:'Methodology'}[view];history.replaceState(null,'','#'+view);}
 function renderResult(){const top=result.ranked[0],sense=senseById(top.id),resolved=result.status==='resolved';$('result-state').textContent=resolved?'Context match':result.status==='tied'?'Tied evidence':'More context needed';
  $('selected-result').innerHTML=resolved?`<div class="sense-word">${esc(result.word)}<span class="pos">noun</span></div><div class="synset-id">${esc(sense.id)}</div><p class="sense-definition">${esc(sense.definition)}</p>${sense.examples.length?`<blockquote class="sense-example">“${esc(sense.examples[0])}”</blockquote>`:''}<div class="synonym-row">ALSO KNOWN AS ${sense.lemmas.slice(0,5).map(w=>`<span>${esc(w)}</span>`).join('')}</div><div class="result-bottom"><div><div class="score-caption">LEXICAL EVIDENCE</div><div class="score-value">${result.score} <small>points · ${top.matches.length} overlapping words</small></div></div><button class="text-button" id="explore-selected">Explore this sense ↗</button></div>`:`<div class="empty-result"><div class="sense-word">${esc(result.word)}<span class="pos">noun</span></div><h3>${result.status==='tied'?'Two or more meanings fit.':'Let’s add a little context.'}</h3><p>${result.status==='tied'?'The highest scores are equal, so no sense is selected. Add a specific clue or inspect the candidates.':'No context words overlap with the sense signatures. Add a descriptive word to the sentence.'}</p><div class="notice">No automatic fallback: the system abstains rather than presenting a guess as a result.</div></div>`;
  const matches=new Set(resolved?top.matches:[]);$('context-tokens').innerHTML=result.context.length?result.context.map(w=>`<span class="token ${matches.has(w)?'matched':''}">${esc(w)}</span>`).join(''):'<span class="loading-hint">No content words remain after filtering.</span>';
  $('candidate-count').textContent=result.ranked.length+' meanings';$('candidates').innerHTML=result.ranked.map((r,i)=>{const s=senseById(r.id);return`<button class="candidate-row" data-sense="${esc(r.id)}" title="${esc(s.definition)}"><span class="candidate-title">${i+1}. ${esc(s.lemmas[0])} <span>· ${esc(s.definition)}</span></span><span class="bar"><i style="width:${result.score?r.score/result.score*100:0}%"></i></span><span class="candidate-score">${r.score}</span></button>`;}).join('');
  $('char-count').textContent=$('sentence').value.length+' / 2000';if($('explore-selected'))$('explore-selected').onclick=()=>openSense(result.word,result.selected);for(const b of $('candidates').querySelectorAll('button'))b.onclick=()=>openSense(result.word,b.dataset.sense);
 }
 function run(){try{result=analyze($('sentence').value,$('target').value,DATA.inventory,$('algorithm').value);$('input-error').hidden=true;$('download-result').disabled=false;renderResult();return result;}catch(e){$('input-error').textContent=e.message;$('input-error').hidden=false;$('result-state').textContent='Previous result shown';$('download-result').disabled=true;return null;}}
 function download(name,data,type='application/json'){const blob=new Blob([typeof data==='string'?data:JSON.stringify(data,null,2)],{type});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 function openSense(word,id){showView('explorer');if($('explore-word')){$('explore-word').value=word;$('sense-search').value='';renderExplorer(id);}}
 async function init(){try{const response=await fetch('assets/wordnet-data.json');if(!response.ok)throw Error('The WordNet data could not be loaded.');DATA=await response.json();$('target').innerHTML=DATA.words.map(w=>`<option value="${w}">${w}</option>`).join('');$('sense-count').textContent=DATA.sense_count;
   $('sample-chips').innerHTML=[['River bank',DATA.samples[1]],['Flying bat',DATA.samples[2]],['Computer mouse',DATA.samples[11]]].map(([label,s])=>`<button type="button" class="chip" data-sample="${s.id}">${label} ↗</button>`).join('');for(const b of $('sample-chips').querySelectorAll('button'))b.onclick=()=>{const s=DATA.samples.find(s=>s.id===b.dataset.sample);$('sentence').value=s.sentence;$('target').value=s.word;run();};
   const markDirty=()=>{$('result-state').textContent='Input changed · analyze again';$('download-result').disabled=true;};$('analysis-form').onsubmit=e=>{e.preventDefault();run();};$('sentence').oninput=()=>{$('char-count').textContent=$('sentence').value.length+' / 2000';markDirty();};$('target').onchange=markDirty;$('algorithm').onchange=markDirty;$('download-result').onclick=()=>{if(result)download('sense-atlas-result.json',result);};
   for(const b of document.querySelectorAll('.nav'))b.onclick=()=>showView(b.dataset.view);$('how-link').onclick=e=>{e.preventDefault();showView('methodology');};document.querySelector('.brand').onclick=e=>{e.preventDefault();showView('workspace');};
   initViews();run();$('loading').hidden=true;showView(location.hash.slice(1)||'workspace');registerTools();
  }catch(e){$('loading').innerHTML=`<div class="error-screen"><h1>We couldn’t load the workspace.</h1><p>${esc(e.message)}</p><p>Start the local server using the README instructions, then reload this page.</p><button class="primary" onclick="location.reload()">Try again</button></div>`;}}
 const heading=(eyebrow,title,subtitle)=>`<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}<span>.</span></h1><p>${subtitle}</p></div><span class="edition">LAB EXERCISE <b>05</b></span></div>`;
 function initViews(){
  $('explorer').innerHTML=heading('THE WORDNET LEXICON','One word. A world of meanings','Explore every noun sense and the lexical relations that connect it.')+`<div class="toolbar"><label for="explore-word" class="sr-only">Word to explore</label><select id="explore-word">${DATA.words.map(w=>`<option>${w}</option>`).join('')}</select><label for="sense-search" class="sr-only">Search senses</label><input id="sense-search" type="search" placeholder="Search definitions or synonyms…"><button class="text-button" id="download-inventory">Download inventory ↗</button></div><div class="section-head"><div><h2 id="inventory-heading"></h2><p>WordNet order is a lexicon convention, not your sentence’s ranking.</p></div></div><div id="sense-list" class="sense-grid"></div><section class="panel relation-panel" id="relations" aria-live="polite"></section>`;
  $('explore-word').onchange=()=>{$('sense-search').value='';renderExplorer();};$('sense-search').oninput=()=>renderExplorer();$('download-inventory').onclick=()=>download('sense-inventory.json',DATA.inventory);renderExplorer();
  $('evaluation').innerHTML=heading('ANNOTATED SAMPLE COLLECTION','Look beyond the prediction','Compare two methods on the same 24 manually labelled educational sentences.')+`<div class="toolbar"><label for="eval-mode" class="sr-only">Evaluation algorithm</label><select id="eval-mode"><option value="extended">Extended Lesk</option><option value="classic">Gloss-only Lesk</option></select><label for="eval-filter" class="sr-only">Filter results</label><select id="eval-filter"><option value="all">All results</option><option value="correct">Correct predictions</option><option value="unresolved">Abstentions</option><option value="incorrect">Incorrect predictions</option></select><button class="text-button" id="download-samples">Export all results ↗</button></div><div id="evaluation-metrics" class="metrics-grid"></div><div class="notice"><b>A demonstration set, not a benchmark.</b> These sentences were authored with knowledge of the sense definitions. Many reuse gloss vocabulary. Scores describe this small, curated set and should not be treated as performance on unseen text. Both methods achieve the same aggregate accuracy here.</div><div class="table-wrap"><table><caption class="sr-only">Predictions compared with manually assigned WordNet senses</caption><thead><tr><th>Target / context</th><th>Gold sense</th><th>Predicted sense</th><th>Outcome</th><th>Inspect</th></tr></thead><tbody id="evaluation-rows"></tbody></table></div><p id="evaluation-count" class="loading-hint"></p>`;
  $('eval-mode').onchange=renderEvaluation;$('eval-filter').onchange=renderEvaluation;$('download-samples').onclick=()=>{const keys=['id','word','sentence','gold','mode','selected','status','score','correct'],quote=v=>'"'+String(v??'').replaceAll('"','""')+'"';download('wsd-results.csv',[keys.join(','),...DATA.results.map(r=>keys.map(k=>quote(r[k])).join(','))].join('\r\n'),'text/csv;charset=utf-8');};renderEvaluation();
  $('methodology').innerHTML=heading('HOW SENSE ATLAS THINKS','Evidence you can follow','A knowledge-based WSD pipeline grounded in Princeton WordNet 3.0.')+`<div class="method-grid"><article class="panel prose"><h2>From a sentence to a sense</h2><p>Word sense disambiguation selects a word’s intended meaning in context. Sense Atlas implements a deterministic Lesk-style overlap method: compare the content words in your sentence with each candidate’s lexical signature.</p><h3>1. A real sense inventory</h3><p>NLTK extracts all 90 noun synsets for 12 ambiguous English words from WordNet 3.0. Each record includes synonyms, a definition, usage examples, hypernyms (broader concepts), hyponyms (more specific concepts), meronyms (parts, members or substances), and lemma-level antonyms when available.</p><h3>2. Normalize the context</h3><p>Lowercase, keep alphabetic tokens of at least two letters, remove a fixed stopword list, exclude the exact target word, and deduplicate. This implementation does not stem, lemmatize, resolve negation, or use word order. The target is interpreted as a noun; verbs and other parts of speech are outside the scope.</p><h3>3. Compare two signatures</h3><p><b>Gloss-only Lesk:</b> the candidate definition, with one point per overlapping word.<br><b>Extended Lesk:</b> definitions and synonyms (weight 3), examples (weight 2), direct hypernym and hyponym definitions and lemmas (weight 1). If a word occurs in multiple fields, use its highest weight once. These are custom Lesk-style variants, not calls to NLTK’s built-in lesk function.</p><pre>score(sense, context) =
  sum of signature weights
  for distinct overlapping context words</pre><h3>4. Explain or abstain</h3><p>Select a sense only when its score is positive and uniquely highest. A tie or zero-overlap result produces an explicit abstention. Candidate order breaks display ties only; it never silently selects a winner. Scores and margins are lexical evidence, not calibrated confidence or probabilities.</p><h3>What the evaluation can tell us</h3><p>Accuracy counts correct predictions out of all 24 samples, treating abstentions as misses. Coverage counts non-abstained predictions. Selective accuracy uses only resolved predictions. There is no training phase or held-out benchmark. Broader signatures do not improve aggregate accuracy on this set.</p><h3>Limitations</h3><p>Only the 12 listed noun targets are supported. No word embeddings or large language model are used. Inflections, paraphrases, short contexts, figurative language and negation can defeat exact overlap. Long signatures can favour broad senses. Human judgement is still needed for unclear contexts.</p><h3>References and attribution</h3><p><a href="https://www.nltk.org/howto/wordnet.html" target="_blank" rel="noopener">NLTK WordNet interface ↗</a><br><a href="https://www.nltk.org/api/nltk.wsd.html" target="_blank" rel="noopener">NLTK WSD / Lesk documentation ↗</a><br><a href="https://wordnet.princeton.edu/" target="_blank" rel="noopener">Princeton WordNet ↗</a><br><a href="WORDNET-LICENSE.txt" target="_blank">WordNet license and copyright notice ↗</a></p></article><aside><article class="panel prose"><h2>The pipeline</h2><div class="pipeline"><div><b>01</b>Sentence + target word</div><div><b>02</b>Context tokenization &amp; filtering</div><div><b>03</b>Candidate WordNet noun senses</div><div><b>04</b>Weighted signature overlap</div><div><b>05</b>Unique winner or abstention</div><div><b>06</b>Evidence, relations &amp; annotation</div></div></article><article class="panel prose" style="margin-top:20px"><h2>Your lab deliverables</h2><p>All generated outputs are available locally. WordNet data are bundled; sentence analysis happens in the browser without an API key.</p><div class="file-list"><a href="downloads/sense_inventory.json" download>Sense inventory <span>JSON ↗</span></a><a href="downloads/wsd_results.csv" download>WSD results and annotations <span>CSV ↗</span></a><a href="downloads/evaluation.json" download>Evaluation metrics <span>JSON ↗</span></a><a href="downloads/analysis_report.md" download>Analysis report <span>MD ↗</span></a></div></article></aside></div>`;
 }
 function renderExplorer(selectedId){const word=$('explore-word').value,query=$('sense-search').value.toLowerCase().trim(),senses=DATA.inventory[word],filtered=senses.filter(s=>(s.definition+' '+s.lemmas.join(' ')+' '+s.id).toLowerCase().includes(query));$('inventory-heading').textContent=word+' · '+filtered.length+' of '+senses.length+' meanings';const selected=filtered.find(s=>s.id===selectedId)||filtered[0];
  $('sense-list').innerHTML=filtered.length?filtered.map(s=>`<button class="sense-card ${s===selected?'selected':''}" data-id="${esc(s.id)}" aria-pressed="${s===selected}"><h3>${esc(s.lemmas[0])}<span class="pos">noun</span></h3><p>${esc(s.definition)}</p><code>${esc(s.id)}</code></button>`).join(''):'<div class="notice">No senses match this search. Try a shorter word or clear the search.</div>';
  for(const b of $('sense-list').querySelectorAll('button'))b.onclick=()=>renderExplorer(b.dataset.id);
  if(!selected){$('relations').hidden=true;return;}$('relations').hidden=false;
  const relationColumn=(title,subtitle,items)=>`<div class="relation-column"><h3>${title}</h3><p>${subtitle}</p>${items.length?items.map(r=>`<div class="relation-item">${esc(r.lemmas[0])}<small>${esc(r.id)}</small><small>${esc(r.definition)}</small></div>`).join(''):'<p>No direct relation listed in WordNet for this sense.</p>'}</div>`;
  $('relations').innerHTML=`<div class="section-head"><div><div class="eyebrow">LEXICAL RELATIONS</div><h2>${esc(selected.lemmas[0])}</h2><p>${esc(selected.id)} · ${esc(selected.definition)}</p></div></div><div class="synonym-row">SYNONYMS ${selected.lemmas.map(l=>`<span>${esc(l)}</span>`).join('')}</div>${selected.examples.length?`<p class="sense-example">${selected.examples.map(e=>'“'+esc(e)+'”').join('<br>')}</p>`:''}<div class="relation-grid">${relationColumn('↑ Hypernyms','Broader concepts · is a kind of',selected.hypernyms)}${relationColumn('↓ Hyponyms','More specific kinds of this concept',selected.hyponyms)}${relationColumn('◇ Meronyms','Parts, members or substances',selected.meronyms)}</div><p class="loading-hint">Antonyms: ${selected.antonyms.length?selected.antonyms.map(esc).join(', '):'none recorded for this sense’s lemmas.'}</p>`;
 }
 function renderEvaluation(){const mode=$('eval-mode').value,m=DATA.evaluation[mode],filter=$('eval-filter').value,all=DATA.results.filter(r=>r.mode===mode),rows=all.filter(r=>filter==='all'||filter==='correct'&&r.correct||filter==='unresolved'&&r.status!=='resolved'||filter==='incorrect'&&r.status==='resolved'&&!r.correct);const pct=v=>(100*v).toFixed(1)+'%';
  $('evaluation-metrics').innerHTML=[['Accuracy',pct(m.accuracy),`${m.correct} / ${m.total} correct; abstentions count as misses`],['Coverage',pct(m.coverage),`${m.resolved} / ${m.total} received a prediction`],['Selective accuracy',m.selective_accuracy===null?'N/A':pct(m.selective_accuracy),'Correct among resolved predictions only'],['Abstentions',String(m.total-m.resolved),'Tied or absent lexical evidence']].map(([label,value,note])=>`<div class="metric-card"><small>${label}</small><b>${value}</b><p>${note}</p></div>`).join('');
  $('evaluation-rows').innerHTML=rows.length?rows.map(r=>`<tr><td><b>${esc(r.word)}</b><br>${esc(r.sentence)}</td><td><code>${esc(r.gold)}</code></td><td><code>${esc(r.selected||'No sense selected')}</code></td><td><span class="status ${r.correct?'':'unclear'}">${r.correct?'Correct':r.status==='tied'?'Tied':r.status==='no_evidence'?'No evidence':'Incorrect'}</span></td><td><button class="text-button" data-example="${r.id}">Try ↗</button></td></tr>`).join(''):'<tr><td colspan="5">No results in this category.</td></tr>';$('evaluation-count').textContent=`Showing ${rows.length} of ${all.length} examples. Gold senses are manually assigned WordNet synset IDs.`;
  for(const b of $('evaluation-rows').querySelectorAll('button'))b.onclick=()=>{const s=DATA.samples.find(s=>s.id===b.dataset.example);$('sentence').value=s.sentence;$('target').value=s.word;$('algorithm').value=mode;run();showView('workspace');};
 }
 function registerTools(){if(!document.modelContext?.registerTool)return;const lifecycle=new AbortController();addEventListener('pagehide',()=>lifecycle.abort(),{once:true});try{Promise.resolve(document.modelContext.registerTool({name:'analyze_sentence',title:'Disambiguate a sentence',description:'Analyze a supported ambiguous noun in a sentence and update the visible Sense Atlas workspace. This changes only the local page.',inputSchema:{type:'object',properties:{sentence:{type:'string',maxLength:2000},word:{type:'string',enum:DATA.words},mode:{type:'string',enum:['classic','extended']}},required:['sentence','word'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute(input){if(!input||typeof input!=='object'||Object.keys(input).some(k=>!['sentence','word','mode'].includes(k)))throw Error('Invalid input.');const checked=analyze(input.sentence,input.word,DATA.inventory,input.mode??'extended');$('sentence').value=checked.sentence;$('target').value=checked.word;$('algorithm').value=checked.mode;result=checked;renderResult();$('input-error').hidden=true;$('download-result').disabled=false;showView('workspace');return{status:checked.status,selected:checked.selected,score:checked.score,margin:checked.margin};}},{signal:lifecycle.signal})).catch(()=>{});}catch{}}
 init();
}
